fn is_ascii_digit(c: char) -> bool {
    // Check if 'c' is between '0' and '9' by Unicode codepoint comparison
    (c as u32) >= ('0' as u32) && (c as u32) <= ('9' as u32)
}

fn all_digits(s: String) -> bool {
    // Check every character in s; return false if any char is not ASCII digit
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false;
        }
    }
    true
}